package com.oms.order.service;

import com.oms.common.tenant.TenantRouting;
import com.oms.common.task.ScopedWorkExecutor;
import org.springframework.stereotype.Service;
import javax.annotation.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.RefundValues.*;

/** Read-only JDP input, durable independent cursors, short fenced page transactions. */
@Service public class RefundSync {
    @Resource RefundService refunds;
    @Resource RefundGoodsService goods;
    @Resource RefundReturnAutoCreate autoCreate;
    @Resource RefundParcelAutomation parcelAutomation;
    @Resource ConfiguredPushReader reader;
    @Resource OrderCatalog catalog;
    @Resource TenantRouting tenants;
    @Resource RefundSyncLog logs;
    private final ScopedWorkExecutor executor=new ScopedWorkExecutor("refund");
    private final Set<String> active=ConcurrentHashMap.newKeySet();
    private final Set<String> requested=ConcurrentHashMap.newKeySet();
    private OrderRepository repo(){return refunds.repository;}
    Map<String,Object> config(String company,long channel,boolean lock){List<Map<String,Object>> rows=repo().db().query("SELECT * FROM oms_refund_config WHERE company_code=? AND channel_id=?"+(lock?" FOR UPDATE":""),ROW,company,channel);require(rows.size()==1,"请先配置该店铺的退款接入");return rows.get(0);}
    public Map<String,Object> configurations(String company){return m("channels",catalog.channels(company),"sources",reader.choices(company),"configs",repo().db().query("SELECT company_code,channel_id,source_key,seller_nick,enabled,auto_convert,initial_time,cursor_time,revision,interval_seconds,last_error,last_success,next_run FROM oms_refund_config WHERE company_code=? ORDER BY channel_id",ROW,company));}
    public void save(String company,Map<String,Object> body,String actor){long channel=number(body,"channel_id");catalog.validateShop(company,channel);String source=required(body,"source_key",64),seller=required(body,"seller_nick",200),initial=required(body,"initial_time",19);require(!time(initial).isAfter(LocalDateTime.now()),"首次同步时间不能晚于当前时间");long enabled=number(body,"enabled"),convert=number(body,"auto_convert"),interval=number(body,"interval_seconds");require((enabled==0||enabled==1)&&(convert==0||convert==1)&&interval>=10&&interval<=3600,"启用状态或扫描间隔无效");require(reader.configured(company,source),"推送库不存在、未启用或不属于本公司");
        // Capability probe happens before locking local configuration. Credentials never leave the reader.
        if(enabled==1)probe(company,source,seller);
        refunds.tx().execute(s->{List<Map<String,Object>> rows=repo().db().query("SELECT * FROM oms_refund_config WHERE company_code=? AND channel_id=? FOR UPDATE",ROW,company,channel);if(rows.isEmpty()){require(number(body,"revision")==0,"配置不存在，请刷新");repo().db().update("INSERT INTO oms_refund_config(company_code,channel_id,source_key,seller_nick,enabled,auto_convert,initial_time,cursor_time,interval_seconds,updated_by) VALUES (?,?,?,?,?,?,?,?,?,?)",company,channel,source,seller,enabled,convert,initial,initial,interval,actor);}else{Map<String,Object> old=rows.get(0);require(number(old,"revision")==number(body,"revision"),"配置已变化，请刷新后重试");require(text(old,"initial_time").equals(initial),"首次同步时间已固定；补拉请创建独立任务");require(text(old,"source_key").equals(source)&&text(old,"seller_nick").equals(seller),"店铺退款身份及推送来源保存后固定，避免混入其他店铺退款");repo().db().update("UPDATE oms_refund_config SET enabled=?,auto_convert=?,interval_seconds=?,revision=revision+1,updated_by=?,next_run=NOW() WHERE company_code=? AND channel_id=?",enabled,convert,interval,actor,company,channel);}return null;});
    }
    public void test(String company,long channel){Map<String,Object> c=config(company,channel,false);catalog.validateShop(company,channel);probe(company,text(c,"source_key"),text(c,"seller_nick"));}
    private void probe(String company,String source,String seller){try{reader.readRefund(company,source,seller,m("mode","MANUAL","start_time","2000-01-01 00:00:00","end_time","2000-01-01 00:00:00","page_time","2000-01-01 00:00:00","page_refund_id","0"),1);}catch(RuntimeException e){throw new IllegalArgumentException("退款推送库检查失败，请检查来源授权、连接和 jdp_tb_refund 字段；未修改游标");}}
    public Map<String,Object> submit(String company,Map<String,Object> body,String actor){long channel=number(body,"channel_id");catalog.validateShop(company,channel);String key=required(body,"request_key",64);require(key.matches("[A-Za-z0-9_-]{8,64}"),"请求标识无效");String mode=text(body,"mode");require(Arrays.asList("MANUAL","IDS").contains(mode),"请选择时间补拉或指定平台退款单号");List<String> ids="IDS".equals(mode)?ids(body.get("refund_ids")):Collections.emptyList();String start="IDS".equals(mode)?current():required(body,"start_time",19),end="IDS".equals(mode)?start:required(body,"end_time",19);
        if(!"IDS".equals(mode))require(time(start).isBefore(time(end))&&!time(end).isAfter(LocalDateTime.now().plusMinutes(1))&&Duration.between(time(start),time(end)).compareTo(Duration.ofDays(90))<=0,"请选择开始早于结束、最多90天的补拉范围");
        return refunds.tx().execute(s->{Map<String,Object> c=config(company,channel,true);List<Map<String,Object>> old=repo().db().query("SELECT * FROM oms_refund_sync WHERE company_code=? AND channel_id=? AND request_key=?",ROW,company,channel,key);if(!old.isEmpty()){Map<String,Object> t=old.get(0);require(mode.equals(text(t,"mode"))&&("IDS".equals(mode)?strings(t.get("selected_ids")).equals(ids):start.equals(text(t,"start_time"))&&end.equals(text(t,"end_time"))),"请求标识已用于其他补拉范围");return m("id",t.get("id"),"state",t.get("state"));}
            long id=repo().insert("INSERT INTO oms_refund_sync(company_code,channel_id,mode,start_time,end_time,page_time,selected_ids,request_key,actor,source_key,seller_nick) VALUES (?,?,?,?,?,?,?,?,?,?,?)",company,channel,mode,start,end,start,encode(ids),key,actor,c.get("source_key"),c.get("seller_nick"));for(String rid:ids)repo().db().update("INSERT INTO oms_refund_sync_item(company_code,task_id,refund_id) VALUES (?,?,?)",company,id,rid);changed(company,id);return m("id",id,"state","PENDING");});
    }
    public List<Map<String,Object>> tasks(String company){List<Map<String,Object>> rows=repo().db().query("SELECT id,channel_id,mode,start_time,end_time,page_time,page_refund_id,state,attempts,synced_count,last_error,create_time FROM oms_refund_sync WHERE company_code=? ORDER BY id DESC LIMIT 50",ROW,company);repo().messageProgress(company,rows,"REFUND_PULL");return rows;}
    public Map<String,Object> task(String company,long id){List<Map<String,Object>> rows=repo().db().query("SELECT id,channel_id,mode,start_time,end_time,page_time,state,attempts,synced_count,last_error,create_time FROM oms_refund_sync WHERE company_code=? AND id=?",ROW,company,id);require(rows.size()==1,"任务不存在或无权访问");Map<String,Object> t=rows.get(0);repo().messageProgress(company,Collections.singletonList(t),"REFUND_PULL");t.put("items",repo().db().query("SELECT refund_id,result,platform_refund_id,message FROM oms_refund_sync_item WHERE company_code=? AND task_id=? ORDER BY id",ROW,company,id));return t;}
    public void retry(String company,long id){refunds.tx().execute(s->{Map<String,Object> hint=rawTask(company,id,false);config(company,number(hint,"channel_id"),true);Map<String,Object> t=rawTask(company,id,true);require(Arrays.asList("FAILED","RETRY").contains(text(t,"state")),"当前任务无需重试；已完成任务可新建补拉");require(repo().db().queryForObject("SELECT COUNT(*) FROM oms_refund_config WHERE company_code=? AND channel_id=? AND lease_until>NOW()",Long.class,company,t.get("channel_id"))==0,"店铺正在处理，请稍后重试");repo().db().update("UPDATE oms_refund_sync SET state='RETRY',attempts=0,last_error='',work_version=work_version+1,next_attempt=NOW() WHERE company_code=? AND id=?",company,id);changed(company,id);return null;});}
    public Map<String,Object> poll(){int count=0;for(String c:tenants.companies())try(TenantRouting.Binding ignored=tenants.open(c)){if(kick(c))count++;}return m("queued_companies",count);}
    public boolean kick(String company){
        TenantRouting.Route scope=tenants.capture(company);String key=scope.datasource()+"/"+company;
        requested.add(key);if(!active.add(key))return false;
        boolean submitted=executor.submit(scope,()->{
            requested.remove(key);
            try{run(company);}finally{active.remove(key);if(requested.remove(key))kick(company);}
        });
        if(!submitted){active.remove(key);requested.remove(key);}return submitted;
    }
    void run(String company){if(autoCreate!=null)autoCreate.scan(company);if(goods!=null)goods.scan(company);for(Map<String,Object> c:repo().db().query("SELECT channel_id FROM oms_refund_config c WHERE company_code=? AND ((auto_convert=1 AND EXISTS(SELECT 1 FROM oms_platform_refund p WHERE p.company_code=c.company_code AND p.channel_id=c.channel_id AND p.conversion_state='WAITING' AND p.source_state='VALID')) OR (enabled=1 AND next_run<=NOW()) OR EXISTS(SELECT 1 FROM oms_refund_sync t WHERE t.company_code=c.company_code AND t.channel_id=c.channel_id AND t.state IN ('PENDING','RUNNING','RETRY') AND t.next_attempt<=NOW())) ORDER BY next_run,channel_id LIMIT 10",ROW,company))shop(company,number(c,"channel_id"));if(parcelAutomation!=null)parcelAutomation.scan(company);if(repo().gifts()!=null)repo().gifts().scan(company);}
    void fence(String company,long channel,String lease){require(!repo().db().query("SELECT channel_id FROM oms_refund_config WHERE company_code=? AND channel_id=? AND lease_token=? AND lease_until>NOW() FOR UPDATE",ROW,company,channel,lease).isEmpty(),"退款同步租约已失效");}
    boolean claim(String company,long channel,String lease){return repo().db().update("UPDATE oms_refund_config SET lease_token=?,lease_until=DATE_ADD(NOW(),INTERVAL 90 SECOND) WHERE company_code=? AND channel_id=? AND (lease_until IS NULL OR lease_until<NOW())",lease,company,channel)==1;}
    void release(String company,long channel,String lease){repo().db().update("UPDATE oms_refund_config SET lease_token=NULL,lease_until=NULL WHERE company_code=? AND channel_id=? AND lease_token=?",company,channel,lease);}
    Map<String,Object> rawTask(String company,long id,boolean lock){List<Map<String,Object>> rows=repo().db().query("SELECT * FROM oms_refund_sync WHERE company_code=? AND id=?"+(lock?" FOR UPDATE":""),ROW,company,id);require(rows.size()==1,"退款同步任务不存在或不属于当前公司");return rows.get(0);}
    void changed(String company,long id){if(repo().messaging()==null)return;Map<String,Object> row=rawTask(company,id,true);long version=number(row,"work_version");if(!repo().db().queryForList("SELECT id FROM oms_message_outbox WHERE company_code=? AND service_code='order' AND message_type='REFUND_PULL' AND business_id=? AND business_version=? LIMIT 1",company,String.valueOf(id),version).isEmpty())return;repo().messaging().enqueue(company,"REFUND_PULL",id,version,"REFSYNC"+id,id+":"+version,0);}
    void shop(String company,long channel){String lease=token();if(!claim(company,channel,lease))return;
        try{refunds.tx().execute(s->{fence(company,channel,lease);Map<String,Object> c=config(company,channel,true);List<Map<String,Object>> pending=repo().db().query("SELECT * FROM oms_refund_sync WHERE company_code=? AND channel_id=? AND state IN ('PENDING','RUNNING','RETRY') ORDER BY id LIMIT 20 FOR UPDATE",ROW,company,channel);
            // A failed automatic window must be repaired before the cursor may advance past it.
            boolean failed=repo().db().queryForObject("SELECT COUNT(*) FROM oms_refund_sync WHERE company_code=? AND channel_id=? AND mode='AUTO' AND state='FAILED' AND end_time>CAST(? AS DATETIME)",Long.class,company,channel,c.get("cursor_time"))>0;
            if(pending.isEmpty()&&!failed&&number(c,"enabled")==1&&!time(text(c,"next_run")).isAfter(LocalDateTime.now())){LocalDateTime start=time(text(c,"cursor_time")).minusMinutes(2),initial=time(text(c,"initial_time")),end=LocalDateTime.now().minusSeconds(3).withNano(0);if(start.isBefore(initial))start=initial;if(end.isAfter(start.plusDays(1)))end=start.plusDays(1);if(end.isAfter(start)){long id=repo().insert("INSERT INTO oms_refund_sync(company_code,channel_id,mode,start_time,end_time,page_time,selected_ids,request_key,actor,source_key,seller_nick) VALUES (?,?,'AUTO',?,?,?,'[]',?,'定时任务',?,?)",company,channel,start.format(TIME),end.format(TIME),start.format(TIME),token(),c.get("source_key"),c.get("seller_nick"));pending.add(rawTask(company,id,false));}repo().db().update("UPDATE oms_refund_config SET next_run=DATE_ADD(NOW(),INTERVAL ? SECOND) WHERE company_code=? AND channel_id=?",c.get("interval_seconds"),company,channel);}
            for(Map<String,Object> task:pending)changed(company,number(task,"id"));return null;});
            refunds.autoConvert(company,channel);
        }finally{release(company,channel,lease);}
    }
    void commit(String company,long channel,String lease,Map<String,Object> task,List<Map<String,Object>> rows){require(rows.size()<=50,"退款来源返回数量超出单页限制");refunds.tx().execute(s->{fence(company,channel,lease);Map<String,Object> current=rawTask(company,number(task,"id"),true);require(number(current,"work_version")==number(task,"work_version")&&text(current,"page_time").equals(text(task,"page_time"))&&text(current,"page_refund_id").equals(text(task,"page_refund_id"))&&Arrays.asList("PENDING","RUNNING","RETRY").contains(text(current,"state")),"退款同步版本或分页游标已变化");boolean ids="IDS".equals(text(task,"mode"));Set<String> found=new HashSet<>();Map<String,Integer> stats=new HashMap<>();for(Map<String,Object> row:rows){Map<String,Object> result=refunds.ingest(company,channel,text(task,"seller_nick"),row,text(task,"actor"));String outcome=text(result,"outcome");stats.merge(outcome,1,Integer::sum);String rid=text(row,"refund_id");found.add(rid);if(ids)repo().db().update("UPDATE oms_refund_sync_item SET result=?,platform_refund_id=?,message=? WHERE company_code=? AND task_id=? AND refund_id=?",result.get("outcome"),result.get("id"),"已保存平台退款；转单状态请查看平台退款列表",company,task.get("id"),rid);}
            if(ids)for(String rid:(List<String>)task.get("selected_ids"))if(!found.contains(rid))repo().db().update("UPDATE oms_refund_sync_item SET result='NOT_FOUND',message='所选卖家推送库未找到；不代表平台不存在，可能超出JDP覆盖范围' WHERE company_code=? AND task_id=? AND refund_id=?",company,task.get("id"),rid);
            boolean done=ids||rows.size()<50;Map<String,Object> last=rows.isEmpty()?null:rows.get(rows.size()-1);repo().db().update("UPDATE oms_refund_sync SET state=?,page_time=?,page_refund_id=?,synced_count=synced_count+?,new_count=COALESCE(new_count,0)+?,updated_count=COALESCE(updated_count,0)+?,unchanged_count=COALESCE(unchanged_count,0)+?,failed_count=COALESCE(failed_count,0)+?,last_error='',next_attempt=NOW() WHERE company_code=? AND id=?",done?"COMPLETED":"RUNNING",last==null?task.get("page_time"):last.get("jdp_modified"),last==null?task.get("page_refund_id"):last.get("refund_id"),rows.size(),stats.getOrDefault("NEW",0),stats.getOrDefault("UPDATED",0),stats.getOrDefault("DUPLICATE",0)+stats.getOrDefault("OLDER",0),stats.getOrDefault("INVALID",0)+stats.getOrDefault("CONFLICT",0),company,task.get("id"));
            repo().db().update("UPDATE oms_refund_config SET last_error='',last_success=NOW() WHERE company_code=? AND channel_id=? AND lease_token=?",company,channel,lease);
            if(done&&"AUTO".equals(text(task,"mode")))repo().db().update("UPDATE oms_refund_config SET cursor_time=GREATEST(cursor_time,?),last_success=NOW(),last_error='',next_run=DATE_ADD(NOW(),INTERVAL interval_seconds SECOND) WHERE company_code=? AND channel_id=?",task.get("end_time"),company,channel);return null;});}
    @PreDestroy public void close(){executor.close();}
}
